<?php if($assets['css']!==null): ?><link rel="stylesheet" href="/build/<?= esc($assets['css'],'attr') ?>"><?php endif; ?>
<style>.wheel-checklist-entry{max-width:52rem;margin:auto;padding:1rem;overflow-wrap:anywhere}.wheel-checklist-entry form{display:grid;gap:12px}.wheel-checklist-entry input,.wheel-checklist-entry select,.wheel-checklist-entry textarea{box-sizing:border-box;width:100%;min-height:44px;max-width:100%}.wheel-checklist-entry textarea{min-height:6rem}.wheel-checklist-entry a,.wheel-checklist-entry button,.wheel-checklist-entry summary{display:inline-flex;align-items:center;min-height:44px;padding:8px;box-sizing:border-box}.wheel-checklist-entry :focus-visible{outline:3px solid #2563eb;outline-offset:3px}.wheel-checklist-entry fieldset{min-width:0}</style></head>
<body class="fleet-shell"><main class="wheel-checklist-entry" id="main-content">
<?php $url = \App\Services\Fleet\VehicleWheelChecklistService::actionUrl((int)$context['id'],$wheel_code,$action); $label=['new'=>'Record new curb rash','worsening'=>'Record worsening','unchanged'=>'Confirm unchanged'][$action]; $value=static fn(string $key,mixed $fallback=''):mixed=>$formData[$key]??$fallback; $time=static fn(mixed $v):string=>str_replace(' ','T',substr((string)$v,0,16)); ?>
<p><a href="/operations/checklists/<?= (int)$context['id'] ?>#known-vehicle-damage">Back to Current Known Damage</a></p><h1><?= esc($label) ?> · <?= esc(\App\Services\Fleet\VehicleWheelIdentity::label($wheel_code)) ?></h1>
<p>Pickup checklist #<?= (int)$context['id'] ?> · <?= esc($context['turo_reservation_id']) ?>. This report is optional and does not change movement readiness. Trip association does not establish guest responsibility.</p>
<?php if($notice!==null): ?><p role="status"><?= esc($notice) ?></p><?php endif; ?>
<?php if($errors!==[]): ?><div id="wheel-errors" role="alert" tabindex="-1"><strong>Wheel report was not saved.</strong><ul><?php foreach($errors as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if($condition!==null): ?><section aria-label="Current wheel condition"><h2>Current condition</h2><p><?= esc($condition['description']) ?></p><p>Severity: <?= esc(\App\Services\Fleet\VehicleDamageService::SEVERITIES[$condition['severity_code']]) ?></p><?php if($projected['latest_physical_occurrence']!==null): ?><p>Latest physical report: <?= esc($projected['latest_physical_occurrence']['note']) ?></p><?php endif; ?></section><?php endif; ?>
<p><a href="/fleet/vehicles/<?= (int)$context['fleet_vehicle_id'] ?>/wheel-history/<?= esc($wheel_code,'attr') ?>">Review photos/history</a></p>
<?php if($prior!==null): ?><details><summary>Prior recorded comparison</summary><h2><?= esc($prior['comparison']['heading']) ?></h2><p><?= esc($prior['comparison']['before']??'Baseline description was not frozen in this occurrence.') ?></p><p>This is the prior occurrence's stored comparison for <?= esc($prior['member']['turo_reservation_id']??'its recorded trip context') ?>. It is not a new inspection for this checklist.</p><a href="<?= esc($prior['url'],'attr') ?>">Review frozen comparison and private photos</a></details><?php else: ?><p>No documented pre-trip baseline. Review available history before reporting.</p><?php endif; ?>
<?php if($pending!==null): ?>
<?php if((int)($pending['payload']['checklist_id']??0)===(int)$context['id'] && ($pending['payload']['wheel_code']??null)===$wheel_code && $pending['action']===$action && $context['can_record']): ?><form method="post" action="<?= esc($url,'attr') ?>"><?= csrf_field() ?><input type="hidden" name="recover" value="1"><p>The previous save needs verification before another command.</p><button type="submit">Recover pending save</button></form>
<?php else: ?><p>Recover the pending save in its original wheel workflow.</p><a href="/fleet/vehicles/<?= (int)$context['fleet_vehicle_id'] ?>/wheel-damage/new">Review pending save</a><?php endif; ?>
<?php elseif(!$canRecord): ?><p role="alert"><?= esc($context['read_only_reason']??'Wheel state changed or needs review. Reload the checklist before choosing an action. This action has not been reinterpreted.') ?></p>
<?php else: ?>
<p id="clock-help">Clock positions are referenced with the valve stem at 12 o'clock.</p>
<?php if($action==='unchanged'): ?><p id="unchanged-help">This records an observation that the existing wheel damage appears unchanged. It does not assign responsibility to the current guest.</p><?php endif; ?>
<form id="staging-wheel-form" method="post" enctype="multipart/form-data" action="<?= esc($url,'attr') ?>" aria-describedby="clock-help<?= $action==='unchanged'?' unchanged-help':'' ?><?= $errors!==[]?' wheel-errors':'' ?>">
<?= csrf_field() ?><input type="hidden" name="command_uuid" value="<?= esc($value('command_uuid',$commandUuid),'attr') ?>"><input type="hidden" name="expected_wheel_state" value="<?= esc($value('expected_wheel_state',$state['fingerprint']),'attr') ?>">
<?php if($action!=='unchanged' && $prior!==null && $prior['member']['condition_event_id']!==null && $prior['member']['panel_code']===\App\Services\Fleet\VehicleWheelIdentity::panel($wheel_code) && $prior['member']['damage_type_code']==='wheel_curb_rash'): ?>
<?php $reference=(int)$prior['member']['condition_event_id'].':'.(int)$prior['member']['id']; ?>
<label for="wheel-baseline">Comparison basis (optional)</label><select id="wheel-baseline" name="baseline_reference"><option value="">No baseline selected</option><option value="<?= esc($reference,'attr') ?>"<?= $value('baseline_reference')===$reference?' selected':'' ?>>Use this last recorded <?= $prior['member']['effect_code']==='observed_existing'?'observation':'condition' ?></option></select>
<p><?= esc($prior['member']['note']) ?> · recorded <?= esc($prior['member']['created_at']) ?>. Selecting this freezes its exact recorded event as comparison evidence; it does not establish guest responsibility.</p>
<?php endif; ?>
<?php if($condition!==null): ?><input type="hidden" name="condition_id" value="<?= esc((string)$value('condition_id',$condition['id']),'attr') ?>"><input type="hidden" name="expected_condition_state" value="<?= esc($value('expected_condition_state',$state['candidates'][0]['fingerprint']),'attr') ?>"><?php endif; ?>
<label for="wheel-note"><?= $action==='unchanged'?'Observation note':'Describe '.($action==='new'?'the new curb rash':'what became worse') ?></label><textarea id="wheel-note" name="note" maxlength="2000" required aria-describedby="clock-help<?= $errors!==[]?' wheel-errors':'' ?>"><?= esc($value('note')) ?></textarea>
<?php if($action==='unchanged'): ?><label for="wheel-observed">Observed at (Honolulu)</label><input id="wheel-observed" type="datetime-local" name="observed_at" value="<?= esc($time($value('observed_at',date('Y-m-d H:i:s'))),'attr') ?>" required><p>Submitting explicitly records this observation time. No observation is recorded when the page opens.</p>
<?php else: ?><label for="wheel-severity">Severity after this report</label><select id="wheel-severity" name="severity_code" required><?php foreach(\App\Services\Fleet\VehicleDamageService::SEVERITIES as $code=>$text): ?><option value="<?= esc($code,'attr') ?>"<?= $value('severity_code',$condition['severity_code']??'cosmetic')===$code?' selected':'' ?>><?= esc($text) ?></option><?php endforeach; ?></select>
<label for="wheel-discovered">Discovered at (Honolulu)</label><input id="wheel-discovered" type="datetime-local" name="discovered_at" value="<?= esc($time($value('discovered_at',date('Y-m-d H:i:s'))),'attr') ?>" required><label for="wheel-occurred">Known occurrence time (optional)</label><input id="wheel-occurred" type="datetime-local" name="occurred_at" value="<?= esc($time($value('occurred_at')),'attr') ?>">
<label for="wheel-attribution">Attribution</label><select id="wheel-attribution" name="attribution_type"><?php foreach(\Config\VehicleDamage::ATTRIBUTIONS as $code=>$text): ?><option value="<?= esc($code,'attr') ?>"<?= $value('attribution_type','unknown')===$code?' selected':'' ?>><?= esc($text) ?></option><?php endforeach; ?></select><label for="wheel-reason">Supporting reason (required for suspected or operator-attributed cause)</label><textarea id="wheel-reason" name="reason" maxlength="2000"><?= esc($value('reason')) ?></textarea><?php endif; ?>
<?= view('vehicle_wheel_damage/_photos', ['formData'=>$formData]) ?>
<button class="primary-action" type="submit"><?= esc($label) ?></button></form><?php endif; ?>
</main></body></html>
